using DriveOS.Modules.TrainingDelivery.Domain.Incidents; using DriveOS.SharedKernel.Identifiers; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.TrainingDelivery.Infrastructure.Persistence.Configurations;
internal sealed class TrainingIncidentEvidenceConfiguration : IEntityTypeConfiguration<TrainingIncidentEvidence>{public void Configure(EntityTypeBuilder<TrainingIncidentEvidence>b){b.ToTable("training_incident_evidence");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new TrainingIncidentEvidenceId(x));b.Property(x=>x.TrainingIncidentId).HasConversion(x=>x.Value,x=>new TrainingIncidentId(x)).IsRequired();b.Property(x=>x.AddedByUserId).HasConversion(x=>x.Value,x=>new UserId(x)).IsRequired();b.Property(x=>x.EvidenceType).HasMaxLength(100).IsRequired();b.Property(x=>x.Description).HasMaxLength(1000);b.HasIndex(x=>new{x.TrainingIncidentId,x.DocumentId});}}
